/* ATRAC9 decoder. */

#include <stdlib.h>
#include <string.h>

#include <retro_inline.h>
#include <formats/ratrac9.h>

#if !defined(RATRAC9_NO_SIMD)
#if defined(__SSE2__) || defined(_M_X64) || (defined(_M_IX86_FP) && _M_IX86_FP >= 2)
#include <emmintrin.h>
#define R9_SSE2 1
#elif defined(__aarch64__) || defined(_M_ARM64)
#include <arm_neon.h>
#define R9_NEON 1
#endif
#endif

/* The output must match plain double arithmetic exactly, so no fused
 * multiply-add. GCC's pragma costs speed, so only where FMA exists. */
#if defined(__clang__)
#pragma STDC FP_CONTRACT OFF
#elif defined(__GNUC__)
#if defined(__FMA__) || defined(__FP_FAST_FMA) || defined(__ARM_FEATURE_FMA)
#pragma GCC optimize ("fp-contract=off")
#endif
#elif defined(_MSC_VER) && _MSC_VER >= 1920
#pragma fp_contract (off)
#endif

#define R9_MAX_CH     8
#define R9_MAX_BLOCKS 5

enum { R9_MONO = 0, R9_STEREO = 1, R9_LFE = 2 };
enum { R9_OUT_S16 = 0, R9_OUT_S32, R9_OUT_F32 };

/* Huffman book: lookup offset, window bits, values per symbol, bits per value,
 * offset of the dequantised values (4 per symbol). */
typedef struct
{
   uint16_t off;
   uint8_t  bits;
   uint8_t  vps;
   uint8_t  vb;
   uint16_t vals;
} r9_book;

